import { classifyRegime, type MacroSnapshot, type Regime } from "./regime.ts";
import type { MacroPack, QuoteBar } from "./types.ts";
import { featureToQuote, featurize, ymd, type FeatureRow, type PackedBars } from "./bars.ts";
import {
  FACTOR_META,
  LOCUS_FACTORS,
  defaultLocusWeights,
  explainFit,
  factorBag,
  locusScore,
  softmaxPos,
  type LocusFactor,
} from "./fit-formula.ts";
import { buildLattice, type LatticePack } from "./lattice.ts";

export type HorizonId = "7D" | "14D" | "21D" | "1M" | "2M" | "1Q" | "6M" | "1Y";

export const BACKTEST_HORIZONS: { id: HorizonId; days: number; labelZh: string }[] = [
  { id: "7D", days: 7, labelZh: "7 日" },
  { id: "14D", days: 14, labelZh: "14 日" },
  { id: "21D", days: 21, labelZh: "21 日" },
  { id: "1M", days: 30, labelZh: "1 月" },
  { id: "2M", days: 42, labelZh: "2 月" },
  { id: "1Q", days: 63, labelZh: "1 季" },
  { id: "6M", days: 126, labelZh: "6 月" },
  { id: "1Y", days: 252, labelZh: "1 年" },
];

export const BACKTEST_SYMBOLS = [
  "^GSPC",
  "^VIX",
  "SPY",
  "QQQ",
  "IWM",
  "DIA",
  "AAPL",
  "MSFT",
  "NVDA",
  "AMZN",
  "META",
  "GOOGL",
  "AMD",
  "TSLA",
  "AVGO",
  "JPM",
  "XOM",
  "WMT",
  "GLD",
  "SLV",
  "TLT",
  "USO",
  "IBIT",
  "BABA",
  "NFLX",
  "TSM",
  "MU",
  "HOOD",
  "PLTR",
  "COIN",
] as const;

export type PanelId = "spx" | "cross";

export type IcCell = {
  factor: string;
  horizon: HorizonId;
  full: number;
  oos: number;
  mag: number;
  n: number;
  nOos: number;
};

export type HitCell = {
  factor: string;
  horizon: HorizonId;
  q5: number;
  q1: number;
  base: number;
  spread: number;
  q5Oos: number;
  baseOos: number;
  meanQ5: number;
  magQ5: number;
  n: number;
  nOos: number;
};

export type ReliabilityBin = {
  bin: number;
  lo: number;
  hi: number;
  hit: number;
  mean: number;
  n: number;
};

export type YearRow = {
  year: number;
  n: number;
  icFit: number;
  icLocus: number;
  hitFit: number;
  hitLocus: number;
  base: number;
};

export type LocusWeightRow = {
  factor: LocusFactor;
  labelZh: string;
  weight: number;
  ic21: number;
};

export type BestHit = {
  panel: PanelId;
  horizon: HorizonId;
  factor: string;
  labelZh: string;
  oosHit: number;
  base: number;
  oosIc: number;
};

export type FitBacktestReport = {
  coverage: {
    first: string;
    last: string;
    years: number;
    nDays: number;
    nSamples: number;
    granularity: "1d";
    names: Array<{ symbol: string; first: string; last: string; n: number }>;
    latticeNames: string[];
  };
  failed: string[];
  source: string;
  caveats: string[];
  horizons: typeof BACKTEST_HORIZONS;
  factors: Array<{ id: string; labelZh: string }>;
  ic: IcCell[];
  hit: HitCell[];
  reliability: ReliabilityBin[];
  yearly: YearRow[];
  locusWeights: LocusWeightRow[];
  best: BestHit;
  bestByHorizon: Record<HorizonId, BestHit>;
  panel: PanelId;
  lattice: LatticePack;
};

const SAMPLE_EVERY = 5;
const WARMUP = 252;
const TRAIN_MIN = 80;
const WEIGHT_HORIZON: HorizonId = "21D";

export function rank(xs: number[]): number[] {
  const idx = xs.map((v, i) => [v, i] as const).sort((a, b) => a[0] - b[0]);
  const ranks = new Array<number>(xs.length);
  for (let r = 0; r < idx.length; ) {
    let j = r;
    while (j + 1 < idx.length && idx[j + 1][0] === idx[r][0]) j++;
    const avg = (r + j) / 2 + 1;
    for (let k = r; k <= j; k++) ranks[idx[k][1]] = avg;
    r = j + 1;
  }
  return ranks;
}

export function pearson(a: number[], b: number[]) {
  const n = a.length;
  if (n < 8) return 0;
  let sa = 0;
  let sb = 0;
  let sa2 = 0;
  let sb2 = 0;
  let sab = 0;
  for (let i = 0; i < n; i++) {
    sa += a[i];
    sb += b[i];
    sa2 += a[i] * a[i];
    sb2 += b[i] * b[i];
    sab += a[i] * b[i];
  }
  const cov = sab - (sa * sb) / n;
  const va = sa2 - (sa * sa) / n;
  const vb = sb2 - (sb * sb) / n;
  if (va <= 1e-18 || vb <= 1e-18) return 0;
  return cov / Math.sqrt(va * vb);
}

export function spearman(x: number[], y: number[]) {
  if (x.length !== y.length || x.length < 8) return 0;
  return pearson(rank(x), rank(y));
}

function keyOf(sym: string) {
  const s = sym.trim().toUpperCase();
  if (s === "^GSPC" || s === "GSPC" || s === "^SPX") return "GSPC";
  if (s === "^VIX" || s === "VIX") return "VIX";
  return s.replace(/[^A-Z0-9.-]/g, "") || s;
}

type Sample = {
  t: number;
  year: number;
  ymd: string;
  symbol: string;
  factors: Record<LocusFactor, number>;
  locus: number;
  fwd: Partial<Record<HorizonId, number>>;
  oos: boolean;
};

function emptyMacro(partial: Partial<MacroPack> & Pick<MacroPack, "vix" | "qqqChg" | "spyChg" | "vixPctile" | "qqqVs50">): MacroPack {
  return {
    vix3m: partial.vix * 1.05,
    vix9d: partial.vix * 0.95,
    vix1d: partial.vix,
    vixChg: 0,
    tnx: 0,
    y2: 0,
    curve: 0,
    irx: 0,
    dxy: 0,
    dxyChg: 0,
    hyg: 0,
    hygChg: 0,
    lqd: 0,
    tlt: 0,
    tltChg: 0,
    qqq: 0,
    spy: 0,
    tqqq: 0,
    tqqqChg: 0,
    iwm: 0,
    iwmChg: 0,
    asOf: 0,
    source: "backtest",
    ...partial,
  };
}

function stubRegime(row: FeatureRow, vixPx: number | null, vixChg: number, tltChg: number, qqqChg: number): { regime: Regime; macro: MacroPack } {
  const vix = vixPx && vixPx > 0 ? vixPx : Math.max(8, row.rv20 * 100);
  const tsrLike = row.rv60 > 0.04 ? row.rv20 / row.rv60 : 1;
  const vix3m = vix / Math.max(0.5, tsrLike);
  const qqqVs50 = row.ma50 && row.ma50 > 0 ? row.close / row.ma50 - 1 : 0;
  const snap: MacroSnapshot = {
    vix,
    vixChg,
    vix3m,
    vix9d: vix * (tsrLike >= 1 ? 0.92 : 1.04),
    vix1d: Math.abs(row.changePct) * Math.sqrt(252) * 100,
    tnx: 0,
    y2: 0,
    curve: 0,
    irx: 0,
    dxy: 0,
    dxyChg: 0,
    hyg: 0,
    hygChg: 0,
    lqd: 0,
    tlt: 0,
    tltChg,
    qqq: row.close,
    qqqChg,
    spyChg: row.changePct,
    tqqqChg: qqqChg * 3,
    qqqVs50,
    vixPctile: row.ivRankProxy,
  };
  const regime = classifyRegime(snap);
  const macro = emptyMacro({
    vix,
    vixChg,
    vix3m,
    vix9d: snap.vix9d,
    vix1d: snap.vix1d,
    tltChg,
    qqqChg,
    spyChg: row.changePct,
    tqqqChg: qqqChg * 3,
    qqqVs50,
    vixPctile: row.ivRankProxy,
    asOf: row.t * 1000,
  });
  return { regime, macro };
}

function fwdAt(closes: number[], i: number, days: number) {
  const j = i + days;
  if (j >= closes.length) return null;
  const a = closes[i];
  const b = closes[j];
  if (!(a > 0) || !(b > 0)) return null;
  return b / a - 1;
}

function pair(xs: number[], ys: number[]) {
  const a: number[] = [];
  const b: number[] = [];
  for (let i = 0; i < xs.length; i++) {
    if (Number.isFinite(xs[i]) && Number.isFinite(ys[i])) {
      a.push(xs[i]);
      b.push(ys[i]);
    }
  }
  return { a, b };
}

function almostFlat(xs: number[]) {
  if (xs.length < 8) return true;
  let min = xs[0];
  let max = xs[0];
  for (const x of xs) {
    if (x < min) min = x;
    if (x > max) max = x;
  }
  return max - min < 1e-6;
}

function quintileHit(score: number[], fwd: number[]) {
  const n = score.length;
  if (n < 20) {
    return { q5: 0, q1: 0, base: 0, spread: 0, meanQ5: 0, magQ5: 0, n };
  }
  const base = fwd.filter((x) => x > 0).length / n;
  const meanAll = fwd.reduce((s, x) => s + x, 0) / n;
  if (almostFlat(score)) {
    return { q5: base, q1: base, base, spread: 0, meanQ5: meanAll, magQ5: 0.5, n };
  }
  const idx = score.map((v, i) => i).sort((i, j) => score[i] - score[j]);
  const qn = Math.max(4, Math.floor(n / 5));
  const q1i = idx.slice(0, qn);
  const q5i = idx.slice(n - qn);
  const hit = (ii: number[]) => ii.filter((i) => fwd[i] > 0).length / ii.length;
  const mean = (ii: number[]) => ii.reduce((s, i) => s + fwd[i], 0) / ii.length;
  const absMed = [...fwd].map(Math.abs).sort((a, b) => a - b)[Math.floor(n / 2)] ?? 0;
  const mag = q5i.filter((i) => Math.abs(fwd[i]) > absMed).length / q5i.length;
  const q5 = hit(q5i);
  const q1 = hit(q1i);
  return { q5, q1, base, spread: q5 - q1, meanQ5: mean(q5i), magQ5: mag, n };
}

function icOf(score: number[], fwd: number[]) {
  const { a, b } = pair(score, fwd);
  return { ic: spearman(a, b), n: a.length };
}

function magIcOf(score: number[], fwd: number[]) {
  return icOf(
    score,
    fwd.map((x) => Math.abs(x)),
  );
}

function lookupClose(byYmd: Map<string, number>, day: string) {
  return byYmd.get(day);
}

function indexByYmd(bars: PackedBars) {
  const m = new Map<string, number>();
  for (let i = 0; i < bars.t.length; i++) m.set(ymd(bars.t[i]), bars.c[i]);
  return m;
}

function buildSamples(series: Record<string, PackedBars>, names: string[], gspcKey: string): Sample[] {
  const gspc = series[gspcKey];
  const gFeat = featurize(gspc);
  const vixBars = series.VIX ?? series["^VIX"];
  const vixMap = vixBars ? indexByYmd(vixBars) : new Map<string, number>();
  const tltBars = series.TLT;
  const tltMap = tltBars ? indexByYmd(tltBars) : new Map<string, number>();
  const qqqBars = series.QQQ;
  const qqqMap = qqqBars ? indexByYmd(qqqBars) : new Map<string, number>();

  const gByYmd = new Map<string, FeatureRow>();
  for (const row of gFeat) gByYmd.set(ymd(row.t), row);

  const featByName: Record<string, FeatureRow[]> = {};
  for (const name of names) {
    const bars = series[name];
    if (!bars || bars.c.length < WARMUP + 30) continue;
    featByName[name] = featurize(bars);
  }

  const out: Sample[] = [];
  for (const name of Object.keys(featByName)) {
    const bars = series[name];
    const feat = featByName[name];
    for (let i = WARMUP; i < feat.length - 7; i += SAMPLE_EVERY) {
      const row = feat[i];
      const day = ymd(row.t);
      const gRow = name === gspcKey ? row : gByYmd.get(day);
      if (!gRow) continue;
      const vixPx = lookupClose(vixMap, day) ?? null;
      const tltPx = lookupClose(tltMap, day);
      const tltPrev = tltBars ? tltMap.get(ymd(row.t - 86400 * 3)) : undefined;
      const tltChg = tltPx && tltPrev && tltPrev > 0 ? tltPx / tltPrev - 1 : 0;
      const qqqPx = lookupClose(qqqMap, day);
      const qqqPrev = qqqBars ? qqqMap.get(ymd(row.t - 86400 * 3)) : undefined;
      const qqqChg = qqqPx && qqqPrev && qqqPrev > 0 ? qqqPx / qqqPrev - 1 : gRow.changePct;
      const { regime, macro } = stubRegime(gRow, vixPx, 0, tltChg, qqqChg);
      const q = featureToQuote(name === "GSPC" ? "GSPC" : name, row, bars.name);
      const bench: QuoteBar = featureToQuote("GSPC", gRow);
      const explain = explainFit(q, regime, macro, bench);
      const factors = factorBag(explain);
      const fwd: Partial<Record<HorizonId, number>> = {};
      for (const h of BACKTEST_HORIZONS) {
        const f = fwdAt(bars.c, i, h.days);
        if (f !== null) fwd[h.id] = f;
      }
      const year = new Date(row.t * 1000).getUTCFullYear();
      out.push({
        t: row.t,
        year,
        ymd: day,
        symbol: name,
        factors,
        locus: factors.fit,
        fwd,
        oos: false,
      });
    }
  }
  out.sort((a, b) => a.t - b.t || a.symbol.localeCompare(b.symbol));
  return out;
}

function weightsFromTrain(train: Sample[], horizon: HorizonId): { weights: Record<LocusFactor, number>; ics: Record<LocusFactor, number> } {
  const ics = {} as Record<LocusFactor, number>;
  for (const k of LOCUS_FACTORS) {
    const xs: number[] = [];
    const ys: number[] = [];
    for (const s of train) {
      const f = s.fwd[horizon];
      if (f === undefined) continue;
      xs.push(s.factors[k]);
      ys.push(f);
    }
    ics[k] = spearman(xs, ys);
  }
  const usable = LOCUS_FACTORS.filter((k) => (ics[k] ?? 0) > 0);
  if (usable.length === 0 || train.length < TRAIN_MIN) {
    return { weights: defaultLocusWeights(), ics };
  }
  const vec = softmaxPos(LOCUS_FACTORS.map((k) => ics[k]));
  const weights = {} as Record<LocusFactor, number>;
  LOCUS_FACTORS.forEach((k, i) => {
    weights[k] = vec[i];
  });
  return { weights, ics };
}

function applyWalkForward(samples: Sample[]) {
  const years = [...new Set(samples.map((s) => s.year))].sort((a, b) => a - b);
  const byYearRows = new Map<number, Sample[]>();
  for (const s of samples) {
    const arr = byYearRows.get(s.year);
    if (arr) arr.push(s);
    else byYearRows.set(s.year, [s]);
  }

  const byYear = new Map<number, Record<LocusFactor, number>>();
  const trainCountByYear = new Map<number, number>();
  const train: Sample[] = [];
  let firstOos = years[0] ?? 0;

  for (const y of years) {
    trainCountByYear.set(y, train.length);
    const { weights } = weightsFromTrain(train, WEIGHT_HORIZON);
    byYear.set(y, weights);
    if (train.length >= TRAIN_MIN && firstOos === years[0]) firstOos = y;
    const rows = byYearRows.get(y);
    if (rows?.length) train.push(...rows);
  }

  for (const s of samples) {
    const w = byYear.get(s.year) ?? defaultLocusWeights();
    s.locus = locusScore(s.factors, w);
    s.oos = s.year >= firstOos && (trainCountByYear.get(s.year) ?? 0) >= TRAIN_MIN;
  }

  const lastYear = years[years.length - 1] ?? 0;
  const lastTrainLen = trainCountByYear.get(lastYear) ?? 0;
  const lastTrain = train.slice(0, lastTrainLen);
  const latest = weightsFromTrain(lastTrain.length >= TRAIN_MIN ? lastTrain : samples, WEIGHT_HORIZON);
  return { byYear, latest, firstOos };
}

function cellsFor(samples: Sample[], panel: PanelId) {
  const ic: IcCell[] = [];
  const hit: HitCell[] = [];
  const factors = [...LOCUS_FACTORS, "locus"] as const;
  for (const h of BACKTEST_HORIZONS) {
    for (const factor of factors) {
      const xs: number[] = [];
      const ys: number[] = [];
      const oosX: number[] = [];
      const oosY: number[] = [];
      for (const s of samples) {
        const f = s.fwd[h.id];
        if (f === undefined) continue;
        const sc = factor === "locus" ? s.locus : s.factors[factor];
        xs.push(sc);
        ys.push(f);
        if (s.oos) {
          oosX.push(sc);
          oosY.push(f);
        }
      }
      const full = icOf(xs, ys);
      const oos = icOf(oosX, oosY);
      const mag = magIcOf(xs, ys);
      ic.push({
        factor,
        horizon: h.id,
        full: full.ic,
        oos: oos.ic,
        mag: mag.ic,
        n: full.n,
        nOos: oos.n,
      });
      const qFull = quintileHit(xs, ys);
      const qOos = oosX.length >= 20 ? quintileHit(oosX, oosY) : { ...qFull, q5: qFull.q5, base: qFull.base };
      hit.push({
        factor,
        horizon: h.id,
        q5: qFull.q5,
        q1: qFull.q1,
        base: qFull.base,
        spread: qFull.spread,
        q5Oos: qOos.q5,
        baseOos: qOos.base,
        meanQ5: qFull.meanQ5,
        magQ5: qFull.magQ5,
        n: qFull.n,
        nOos: qOos.n,
      });
    }
  }
  void panel;
  return { ic, hit };
}

function reliabilityOf(samples: Sample[], horizon: HorizonId): ReliabilityBin[] {
  const xs: number[] = [];
  const ys: number[] = [];
  for (const s of samples) {
    if (!s.oos) continue;
    const f = s.fwd[horizon];
    if (f === undefined) continue;
    xs.push(s.locus);
    ys.push(f);
  }
  const bins: ReliabilityBin[] = [];
  if (xs.length < 30) return bins;
  const idx = xs.map((_, i) => i).sort((a, b) => xs[a] - xs[b]);
  const size = Math.floor(idx.length / 10) || 1;
  for (let b = 0; b < 10; b++) {
    const slice = b === 9 ? idx.slice(b * size) : idx.slice(b * size, (b + 1) * size);
    if (!slice.length) continue;
    const hit = slice.filter((i) => ys[i] > 0).length / slice.length;
    const mean = slice.reduce((s, i) => s + ys[i], 0) / slice.length;
    bins.push({
      bin: b + 1,
      lo: xs[slice[0]],
      hi: xs[slice[slice.length - 1]],
      hit,
      mean,
      n: slice.length,
    });
  }
  return bins;
}

function yearlyOf(samples: Sample[], horizon: HorizonId): YearRow[] {
  const years = [...new Set(samples.map((s) => s.year))].sort((a, b) => a - b);
  const rows: YearRow[] = [];
  for (const year of years) {
    const chunk = samples.filter((s) => s.year === year);
    const fit: number[] = [];
    const loc: number[] = [];
    const fwd: number[] = [];
    for (const s of chunk) {
      const f = s.fwd[horizon];
      if (f === undefined) continue;
      fit.push(s.factors.fit);
      loc.push(s.locus);
      fwd.push(f);
    }
    if (fwd.length < 12) continue;
    const hFit = quintileHit(fit, fwd);
    const hLoc = quintileHit(loc, fwd);
    rows.push({
      year,
      n: fwd.length,
      icFit: icOf(fit, fwd).ic,
      icLocus: icOf(loc, fwd).ic,
      hitFit: hFit.q5,
      hitLocus: hLoc.q5,
      base: hFit.base,
    });
  }
  return rows;
}

export function pickBestForHorizon(hit: HitCell[], ic: IcCell[], horizon: HorizonId, panel: PanelId = "spx"): BestHit {
  const rows = hit.filter((c) => c.horizon === horizon);
  let best = rows.find((c) => c.factor === "locus") ?? rows[0];
  if (!best) {
    return {
      panel,
      horizon,
      factor: "locus",
      labelZh: FACTOR_META.locus.labelZh,
      oosHit: 0,
      base: 0,
      oosIc: 0,
    };
  }
  for (const c of rows) {
    const edge = c.q5Oos - c.baseOos;
    if (Math.abs(edge) < 0.002 && Math.abs(c.spread) < 0.002) continue;
    const bestEdge = best.q5Oos - best.baseOos;
    if (edge > bestEdge) best = c;
  }
  const icRow = ic.find((c) => c.factor === best.factor && c.horizon === horizon);
  const label = best.factor === "locus" ? FACTOR_META.locus.labelZh : FACTOR_META[best.factor as LocusFactor].labelZh;
  return {
    panel,
    horizon,
    factor: best.factor,
    labelZh: label,
    oosHit: best.q5Oos,
    base: best.baseOos,
    oosIc: icRow?.oos ?? 0,
  };
}

function pickBestAll(hit: HitCell[], ic: IcCell[], panel: PanelId) {
  const bestByHorizon = {} as Record<HorizonId, BestHit>;
  for (const h of BACKTEST_HORIZONS) bestByHorizon[h.id] = pickBestForHorizon(hit, ic, h.id, panel);
  return { best: bestByHorizon["21D"], bestByHorizon };
}

const CAVEATS = [
  "分數是條件匹配，不是下單勝率，更不是必勝。",
  "S&P 500 長端有正股權風險溢價：無條件 21 日上漲比例本來就過半，Q5 必須高出這條基準才有信息。",
  "VIX 只從 1990 年起；更早用 SPX 已實現波動當代理，體制分類會比較粗。",
  "短波 / 值博率天生偏振幅，方向命中可能接近基準——振幅欄（|R| IC）才是它們的主場。",
  "Walk-forward 權重每年用過去樣本估計，當年只看樣本外。重疊視窗會讓 IC 看起來略穩。",
  "相交格子找的是分數帶同時出現時的條件命中，不是單因子 Q5，更不是必勝。",
];

const SKIP_NAMES = new Set(["VIX", "TQQQ", "SQQQ", "UPRO", "TNA"]);

function normalizeSeries(seriesIn: Record<string, PackedBars>) {
  const series: Record<string, PackedBars> = {};
  for (const [k, v] of Object.entries(seriesIn)) {
    const key = keyOf(k);
    series[key] = { ...v, symbol: key };
  }
  return series;
}

function tradableOf(series: Record<string, PackedBars>) {
  return Object.keys(series).filter((k) => !SKIP_NAMES.has(k));
}

function pickNames(series: Record<string, PackedBars>, panel: PanelId, prefer: string[]) {
  const tradable = tradableOf(series);
  const long = tradable
    .filter((k) => k === "GSPC" || series[k].c.length >= WARMUP + 60)
    .sort((a, b) => (series[b]?.c.length ?? 0) - (series[a]?.c.length ?? 0));
  const pref = prefer.map(keyOf);
  const rest = long.filter((k) => k !== "GSPC");
  const head = rest.filter((k) => pref.includes(k));
  const tail = rest.filter((k) => !pref.includes(k));
  return panel === "spx" ? ["GSPC"] : ["GSPC", ...head, ...tail].slice(0, 36);
}

function requireGspc(series: Record<string, PackedBars>) {
  const gspc = series.GSPC;
  if (!gspc || gspc.c.length < WARMUP + 60) {
    throw new Error("需要至少一年以上的 S&P 500 日線才能回測");
  }
  return gspc;
}

function cloneSample(s: Sample): Sample {
  return { ...s, fwd: { ...s.fwd }, factors: { ...s.factors } };
}

function assembleReport(
  series: Record<string, PackedBars>,
  samples: Sample[],
  names: string[],
  panel: PanelId,
  failed: string[],
  latest: { weights: Record<LocusFactor, number>; ics: Record<LocusFactor, number> },
): FitBacktestReport {
  const gspc = series.GSPC;
  const { ic, hit } = cellsFor(samples, panel);
  const lattice = buildLattice(samples);
  const reliability = reliabilityOf(samples, WEIGHT_HORIZON);
  const yearly = yearlyOf(samples, WEIGHT_HORIZON);
  const first = ymd(gspc.t[0]);
  const last = ymd(gspc.t[gspc.t.length - 1]);
  const years = (gspc.t[gspc.t.length - 1] - gspc.t[0]) / (365.25 * 86400);
  const coverageNames = tradableOf(series).map((s) => ({
    symbol: s,
    first: ymd(series[s].t[0]),
    last: ymd(series[s].t[series[s].t.length - 1]),
    n: series[s].c.length,
  }));
  const { best, bestByHorizon } = pickBestAll(hit, ic, panel);
  const locusWeights: LocusWeightRow[] = LOCUS_FACTORS.map((factor) => ({
    factor,
    labelZh: FACTOR_META[factor].labelZh,
    weight: latest.weights[factor],
    ic21: latest.ics[factor],
  })).sort((a, b) => b.weight - a.weight);

  return {
    coverage: {
      first,
      last,
      years,
      nDays: gspc.c.length,
      nSamples: samples.length,
      granularity: "1d",
      names: coverageNames,
      latticeNames: names,
    },
    failed,
    source: "Yahoo Finance delayed · 日線 period1/period2",
    caveats: [...CAVEATS, ...lattice.caveats],
    horizons: BACKTEST_HORIZONS,
    factors: [...LOCUS_FACTORS.map((id) => ({ id, labelZh: FACTOR_META[id].labelZh })), { id: "locus", labelZh: FACTOR_META.locus.labelZh }],
    ic,
    hit,
    reliability,
    yearly,
    locusWeights,
    best,
    bestByHorizon,
    panel,
    lattice,
  };
}

export function runFitBacktest(
  seriesIn: Record<string, PackedBars>,
  opts?: { failed?: string[]; panel?: PanelId; prefer?: string[] },
): FitBacktestReport {
  const series = normalizeSeries(seriesIn);
  requireGspc(series);
  const panel: PanelId = opts?.panel ?? "spx";
  const names = pickNames(series, panel, opts?.prefer ?? []);
  const samples = buildSamples(series, names, "GSPC");
  const { latest } = applyWalkForward(samples);
  return assembleReport(series, samples, names, panel, opts?.failed ?? [], latest);
}

export function reportsBoth(seriesIn: Record<string, PackedBars>, failed: string[] = [], prefer: string[] = []) {
  const series = normalizeSeries(seriesIn);
  requireGspc(series);
  const crossNames = pickNames(series, "cross", prefer);
  const samplesAll = buildSamples(series, crossNames, "GSPC");
  const spxSamples = samplesAll.filter((s) => s.symbol === "GSPC").map(cloneSample);
  const spxWf = applyWalkForward(spxSamples);
  const spx = assembleReport(series, spxSamples, ["GSPC"], "spx", failed, spxWf.latest);
  if (crossNames.length < 2) return { spx, cross: spx };
  try {
    const crossWf = applyWalkForward(samplesAll);
    const cross = assembleReport(series, samplesAll, crossNames, "cross", failed, crossWf.latest);
    return { spx, cross };
  } catch {
    return { spx, cross: spx };
  }
}
